import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A reason on a sheet's list that a claim may be voided for. */
@Entity
@Table(name = "void_reason")
public class VoidReason {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "reason", nullable = false)
    private String reason;

    /** The sheet's today when the reason was added. */
    @Column(name = "added_on", nullable = false)
    private LocalDate addedOn;

    protected VoidReason() {
    }

    public VoidReason(String sheetId, String reason, LocalDate addedOn) {
        this.sheetId = sheetId;
        this.reason = reason;
        this.addedOn = addedOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getReason() {
        return reason;
    }

    public LocalDate getAddedOn() {
        return addedOn;
    }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface VoidReasonRepository extends JpaRepository<VoidReason, Long> {

    /** The void reasons of a sheet in the order they were added. */
    List<VoidReason> findBySheetIdOrderByIdAsc(String sheetId);

    /** Whether the reason is already on the sheet's list. */
    boolean existsBySheetIdAndReason(String sheetId, String reason);

    /** Whether the sheet has any void reason. */
    boolean existsBySheetId(String sheetId);
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The void reasons of a sheet. */
@Service
public class VoidReasonService {

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final Audit audit;

    public VoidReasonService(VoidReasonRepository reasons, SheetService sheets, Audit audit) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The void reasons of the sheet in the order they were added. */
    @Transactional(readOnly = true)
    public List<VoidReason> list(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a (trimmed) reason to the sheet's list; refused when blank or already on the list. */
    @Transactional
    public synchronized VoidReason add(String sheetId, String user, String reason) {
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Enter a void reason");
        }
        sheets.load(sheetId, user);
        if (reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw alreadyListed();
        }
        VoidReason saved;
        try {
            saved = reasons.saveAndFlush(new VoidReason(sheetId, text, sheets.today(sheetId)));
        } catch (DataIntegrityViolationException e) {
            throw alreadyListed();
        }
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + text);
        return saved;
    }

    /** The reason a claim of the sheet is voided with: null when the sheet has no reasons (none is
     *  needed); refused when it has some and the reason given is not one of them. */
    @Transactional(readOnly = true)
    public String required(String sheetId, String reason) {
        if (!reasons.existsBySheetId(sheetId)) {
            return null;
        }
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty() || !reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose a void reason from the sheet's list");
        }
        return text;
    }

    private static ResponseStatusException alreadyListed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That reason is already on the list");
    }
}
-- The claim templates of a sheet, each (trimmed) name at most once: saving a name again replaces
-- its amount and note. A claim made from a template copies them, so it keeps no link to it.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL,
    note     VARCHAR(500)   NOT NULL,
    CONSTRAINT claim_template_unique UNIQUE (sheet_id, name)
);
import { HttpClient } from '@angular/common/http';
import { Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A reason on the sheet's list that a claim may be voided for. */
export interface VoidReason {
  id: number;
  reason: string;
}

// The void reasons of the active sheet, re-read whenever the sheet is loaded. While the list is not
// empty, a claim is voided with one of them.
@Injectable({ providedIn: 'root' })
export class VoidReasons {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's void reasons in the order they were added. */
  readonly list = signal<VoidReason[]>([]);
  private reads = 0;

  constructor() {
    effect(() => {
      this.session.loads();
      const sheetId = this.session.sheetId();
      this.list.set([]);
      if (sheetId) void this.reload(sheetId);
    });
  }

  /** Add a reason to the sheet's list; refused (400) when blank and (409) when already on it. */
  async add(reason: string): Promise<VoidReason> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    const saved = await firstValueFrom(
      this.http.post<VoidReason>(this.url(sheetId), { reason }, { headers: { 'X-User': user } }),
    );
    this.list.update((rs) => [...rs.filter((r) => r.id !== saved.id), saved]);
    return saved;
  }

  private async reload(sheetId: string): Promise<void> {
    const read = ++this.reads;
    try {
      const reasons = await firstValueFrom(this.http.get<VoidReason[]>(this.url(sheetId)));
      if (read === this.reads) this.list.set(reasons);
    } catch {
      // the list stays empty; the next load reads it again
    }
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/void-reasons`;
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { VoidReasons } from '../../core/void-reasons';

// The sheet's void reasons and the entry a reason is added with. While the list is not empty, a
// claim is voided with a reason chosen from it.
@Component({
  selector: 'app-void-reason-form',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="void-reasons-heading">
      <h3 id="void-reasons-heading">Void reasons</h3>
      <form data-testid="void-reason-form" [formGroup]="form" (ngSubmit)="submit()">
        <label for="void-reason-text">Void reason</label>
        <input id="void-reason-text" data-testid="void-reason-text" formControlName="reason" />
        <button type="submit" data-testid="void-reason-add">Add void reason</button>
        @if (error()) {
          <p role="alert" data-testid="void-reason-error">{{ error() }}</p>
        }
      </form>
      <ul data-testid="void-reasons">
        @for (r of reasons.list(); track r.id) {
          <li [attr.data-testid]="'void-reason-row-' + r.reason">{{ r.reason }}</li>
        }
      </ul>
    </section>
  `,
})
export class VoidReasonForm {
  protected readonly reasons = inject(VoidReasons);

  protected readonly error = signal('');
  protected readonly form = new FormGroup({
    reason: new FormControl('', { nonNullable: true }),
  });
  private submitting = false;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const reason = this.form.getRawValue().reason.trim();
    if (reason === '') {
      this.error.set('Enter a void reason.');
      return;
    }
    if (this.reasons.list().some((r) => r.reason === reason)) {
      this.error.set('That reason is already on the list.');
      return;
    }
    this.submitting = true;
    try {
      await this.reasons.add(reason);
      this.form.reset({ reason: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 409
          ? 'That reason is already on the list, or the sheet may not be changed.'
          : e instanceof HttpErrorResponse && e.status === 403
            ? 'A viewer may not add a void reason.'
            : 'The void reason could not be added.',
      );
    } finally {
      this.submitting = false;
    }
  }
}

